'use client'
/** Stepped Slider: the MATRIX card `ui-stepped-slider` (interactive: pointer and keyboard edit its data). Generated by scripts/registry/generate.ts. */
import { MatrixDotCard, type MatrixDotCardProps } from '@/components/matrix/dot-card'
import { componentsBoard } from '@/lib/matrix/widgets/boards/components'

const preset = componentsBoard.find(p => p.id === 'ui-stepped-slider')!

export type MatrixSteppedSliderProps = Omit<MatrixDotCardProps, 'preset'>

export function MatrixSteppedSlider(props: MatrixSteppedSliderProps) {
  return <MatrixDotCard preset={preset} {...props} />
}
